const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 * Reads DATABASE_URL from .env.test for database connection.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Load environment variables from .env.test file
 * @returns {string|null} The DATABASE_URL or null if not found
 */
function loadDatabaseUrl() {
  if (!fs.existsSync(ENV_FILE)) {
    console.log('Warning: .env.test file not found');
    return null;
  }

  const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
  const lines = envContent.split('\n');

  for (const line of lines) {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      continue;
    }

    const [key, ...valueParts] = trimmedLine.split('=');
    if (key.trim() === 'DATABASE_URL') {
      // Rejoin in case the URL contains '=' characters
      let value = valueParts.join('=').trim();
      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }
      return value;
    }
  }

  return null;
}

/**
 * Simulate database connection
 * @param {string} databaseUrl - The database connection string
 */
function connectToDatabase(databaseUrl) {
  if (!databaseUrl) {
    console.log('Error: No DATABASE_URL found in .env.test');
    return false;
  }

  // Parse connection string for display (hide password)
  const urlObj = new URL(databaseUrl);
  const displayUrl = `${urlObj.protocol}//${urlObj.username}:***@${urlObj.host}${urlObj.pathname}`;

  console.log(`Successfully connected to database: ${displayUrl}`);
  return true;
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting migration process...\n');

  // Load and resolve database connection
  console.log('Loading database configuration from .env.test...');
  const databaseUrl = loadDatabaseUrl();

  if (!connectToDatabase(databaseUrl)) {
    console.log('\nMigration aborted: Could not establish database connection.');
    return;
  }

  console.log('');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each filename in order
  migrationFiles.forEach((filename, index) => {
    console.log(`[${index + 1}] Would apply: ${filename}`);
  });

  console.log('\nMigration process complete.');
}

