const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse .env file and extract key-value pairs
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing environment variables
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  const env = {};

  content.split('\n').forEach(line => {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }

    // Parse KEY=value format
    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex > 0) {
      const key = trimmed.slice(0, separatorIndex).trim();
      let value = trimmed.slice(separatorIndex + 1).trim();

      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      env[key] = value;
    }
  });

  return env;
}

/**
 * Resolve database connection string from .env.test
 * @returns {string|null} Database connection URL or null if not found
 */
function resolveConnectionString() {
  const env = parseEnvFile(ENV_FILE);
  return env.DATABASE_URL || null;
}

/**
 * Simulate connecting to the database
 * @param {string} connectionString - Database connection URL
 */
function connectToDatabase(connectionString) {
  // Mask sensitive parts of the connection string for logging
  const maskedUrl = connectionString.replace(/:([^:@]+)@/, ':****@');

  console.log(`Connecting to database: ${maskedUrl}`);
  console.log('Connected successfully!\n');
}

/**
 * Get list of SQL migration files sorted in order
 * @returns {string[]} Array of SQL filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log('Migrations directory does not exist. Creating ./migrations/');
    fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
    return [];
  }

  // Read all files from migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files alphabetically to ensure consistent order
  // Common naming convention: 001_create_users.sql, 002_add_posts.sql, etc.
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Run migrations by logging each filename that would be applied
 */
function runMigrations() {
  console.log('Starting migration process...\n');

  // Resolve and validate connection string
  const connectionString = resolveConnectionString();
  if (!connectionString) {
    console.error('ERROR: DATABASE_URL not found in .env.test');
    console.error('Please create a .env.test file with DATABASE_URL=your_connection_string');
    process.exit(1);
  }

  // Connect to database (simulated)
  connectToDatabase(connectionString);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((filename, index) => {
    console.log(`[${index + 1}/${migrationFiles.length}] Would apply: ${filename}`);
  });

  console.log('\nMigration process completed.');
}

// Run the migrations
runMigrations();

