const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile() {
  if (!fs.existsSync(ENV_FILE)) {
    console.error(`Environment file not found: ${ENV_FILE}`);
    process.exit(1);
  }

  const envContent = fs.readFileSync(ENV_FILE, 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      return;
    }
    // Parse KEY=value format
    const equalIndex = trimmedLine.indexOf('=');
    if (equalIndex > 0) {
      const key = trimmedLine.substring(0, equalIndex).trim();
      let value = trimmedLine.substring(equalIndex + 1).trim();
      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }
      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Parse connection string and extract components
 * @param {string} connectionString - Database connection string
 * @returns {Object} Parsed connection details
 */
function parseConnectionString(connectionString) {
  try {
    const url = new URL(connectionString);
    return {
      protocol: url.protocol.replace(':', ''),
      host: url.hostname,
      port: url.port || '5432',
      database: url.pathname.replace('/', ''),
      user: url.username,
      password: url.password ? '****' : undefined
    };
  } catch (error) {
    return null;
  }
}

/**
 * Simulate database connection
 * @param {string} connectionString - Database connection string
 */
function connectToDatabase(connectionString) {
  const connectionDetails = parseConnectionString(connectionString);

  if (!connectionDetails) {
    console.error('Invalid DATABASE_URL format');
    process.exit(1);
  }

  console.log('Connecting to database...');
  console.log(`  Protocol: ${connectionDetails.protocol}`);
  console.log(`  Host: ${connectionDetails.host}`);
  console.log(`  Port: ${connectionDetails.port}`);
  console.log(`  Database: ${connectionDetails.database}`);
  console.log(`  User: ${connectionDetails.user}`);
  console.log('Connected successfully!\n');
}

/**
 * Get list of SQL migration files sorted in order
 * @returns {string[]} Array of SQL filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  // Read all files from migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files and sort them
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting migration process...\n');

  // Load environment and connect to database
  const env = loadEnvFile();

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  connectToDatabase(env.DATABASE_URL);

  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  migrationFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    console.log(`[${index + 1}] Applying: ${filename}`);

    // Read the SQL file content (in a real migration, this would be executed)
    const sqlContent = fs.readFileSync(filePath, 'utf8');
    // console.log(`    Content preview: ${sqlContent.substring(0, 50)}...`);
  });

  console.log('\nMigration process completed.');
}

// Run the migrations
runMigrations();

