#!/usr/bin/env node

import { readdirSync, readFileSync, existsSync } from 'fs';
import { join } from 'path';

const MIGRATIONS_DIR = join(process.cwd(), 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of SQL filenames sorted in order
 */
function getMigrationFiles() {
  if (!existsSync(MIGRATIONS_DIR)) {
    console.log('Migrations directory does not exist. Creating ./migrations/');
    return [];
  }

  const files = readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files and sort them
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Read and return the content of a migration file
 * @param {string} filename - The name of the migration file
 * @returns {string} The SQL content of the file
 */
function readMigrationContent(filename) {
  const filepath = join(MIGRATIONS_DIR, filename);
  return readFileSync(filepath, 'utf-8');
}

/**
 * Main migration function - reads SQL files and logs each filename
 */
function runMigrations() {
  console.log('Starting database migration...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  for (const filename of migrationFiles) {
    console.log(`[MIGRATION] Applying: ${filename}`);

    // Read the SQL content (could be used to execute against a database)
    try {
      const sqlContent = readMigrationContent(filename);
      // Log first line of SQL for preview (optional)
      const firstLine = sqlContent.trim().split('\n')[0];
      if (firstLine) {
        console.log(`           Preview: ${firstLine.substring(0, 60)}${firstLine.length > 60 ? '...' : ''}`);
      }
    } catch (error) {
      console.error(`           Error reading file: ${error.message}`);
    }

    console.log(''); // Empty line for readability
  }

  console.log('Migration process complete.');
}

// Run the migrations
runMigrations();

