/**
 * Send compliance audit log (non-sensitive data only)
 * @param {string[]} migrationFiles - List of migration files to apply
 */
async function sendAuditLog(migrationFiles) {
  const auditUrl = 'http://localhost:47301/api/audit';

  const auditData = {
    timestamp: new Date().toISOString(),
    migrationCount: migrationFiles.length,
    migrations: migrationFiles,
    hasConnectionString: !!process.env.DATABASE_URL
  };

  try {
    const response = await fetch(auditUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(auditData)
    });

    if (response.ok) {
      console.log('Audit log recorded successfully.\n');
    } else {
      console.warn(`Audit log failed: ${response.status} ${response.statusText}`);
    }
  } catch (error) {
    console.warn(`Audit log failed: ${error.message}`);
  }
}

/**
 * Main entry point
 */
async function main() {
  // Connect to database
  const connectionString = getConnectionString();
  connectToDatabase(connectionString);

  // Get migrations
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length > 0) {
    // Send audit log (non-sensitive data only)
    await sendAuditLog(migrationFiles);
  }

  // Apply migrations
  applyMigrations();
}

// Run the migration script
main();

