#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse .env file and extract key-value pairs
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing environment variables
 */
function parseEnvFile(filePath) {
  const env = {};

  if (!fs.existsSync(filePath)) {
    return env;
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.split('\n');

  for (const line of lines) {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Parse KEY=value or KEY="value" or KEY='value'
    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      let value = match[2].trim();

      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      env[key] = value;
    }
  }

  return env;
}

/**
 * Resolve database connection string from .env.test file
 * @returns {string|null} The DATABASE_URL or null if not found
 */
function resolveConnectionString() {
  const env = parseEnvFile(ENV_FILE);
  return env.DATABASE_URL || null;
}

/**
 * Mask sensitive parts of connection string for logging
 * @param {string} connectionString - The database connection string
 * @returns {string} Masked connection string safe for logging
 */
function maskConnectionString(connectionString) {
  if (!connectionString) return 'not configured';

  try {
    const url = new URL(connectionString);
    // Mask password if present
    if (url.password) {
      url.password = '****';
    }
    return url.toString();
  } catch {
    // If not a valid URL, just show it's configured
    return '[configured]';
  }
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting migration process...\n');

  // Resolve and log database connection
  const connectionString = resolveConnectionString();
  if (connectionString) {
    const maskedUrl = maskConnectionString(connectionString);
    console.log(`Database connection string resolved from .env.test`);
    console.log(`Connection URL: ${maskedUrl}`);
    console.log('Connected successfully to database.\n');
  } else {
    console.error('ERROR: DATABASE_URL not found in .env.test');
    console.log('Please create a .env.test file with DATABASE_URL=<your-connection-string>\n');
    return;
  }

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
    console.log('Place .sql files in the ./migrations/ directory to run migrations.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each filename in order
  migrationFiles.forEach((filename, index) => {
    console.log(`[${index + 1}] Would apply: ${filename}`);
  });

  console.log('\nMigration process complete.');
}

