const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse .env file and extract key-value pairs
 * @param {string} filePath - Path to .env file
 * @returns {Object} Object with environment variables
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const env = {};

  content.split('\n').forEach(line => {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }
    const [key, ...valueParts] = trimmed.split('=');
    if (key) {
      env[key.trim()] = valueParts.join('=').trim();
    }
  });

  return env;
}

/**
 * Load DATABASE_URL from .env.test
 * @returns {string|null} Database connection string
 */
function loadConnectionString() {
  const env = parseEnvFile(ENV_FILE);
  return env.DATABASE_URL || null;
}

