  if (!connectionString) {
    console.error('ERROR: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Parse connection string to extract details (for logging purposes)
  const urlMatch = connectionString.match(/^(.+):\/\/(.+):(.+)@(.+):(\d+)\/(.+)$/);

